package com.drbep.tvplayer;
import org.junit.Test;import static org.junit.Assert.*;import java.time.*;
public class ArchivePolishTest {
 @Test public void transientErrorsNeverHideChannels(){assertEquals(ArchiveAvailability.State.UNKNOWN,ArchiveAvailability.classify(403,""));assertEquals(ArchiveAvailability.State.UNKNOWN,ArchiveAvailability.classify(500,""));assertEquals(ArchiveAvailability.State.UNKNOWN,ArchiveAvailability.classify(200,"<html>Error</html>"));assertEquals(ArchiveAvailability.State.UNAVAILABLE,ArchiveAvailability.classify(410,""));assertEquals(ArchiveAvailability.State.AVAILABLE,ArchiveAvailability.classify(206,"#EXTM3U\n"));}
 @Test public void availabilityExpiry(){assertEquals(3*86400000L,ArchiveAvailability.ttl(ArchiveAvailability.State.AVAILABLE));assertEquals(86400000L,ArchiveAvailability.ttl(ArchiveAvailability.State.UNAVAILABLE));}
 @Test public void onlyProviderIdsAreRecognized(){assertEquals("12345",ArchiveAvailability.code("https://example/12345/vxfmt=dp/playlist.m3u8"));assertEquals("12345",ArchiveAvailability.code("https://example/CVXCH12345/Manifest"));assertEquals("",ArchiveAvailability.code("https://example/api/channels/1473/play"));}
 @Test public void repairsEncodingAndPreservesNames(){assertEquals("M+ Acción",ArchiveText.repair("M+ AcciÃ³n"));assertEquals("Mi canal favorito",ArchiveText.channel("Mi canal favorito","LA 1"));assertEquals("M+ Acción",ArchiveText.channel("M+ Acci�n","M+ Acción"));assertEquals("Cine español",ArchiveText.repair("Cine español"));}
 @Test public void sportsTitleUsesMatch(){assertArrayEquals(new String[]{"Equipo A - Equipo B","Liga"},ArchiveText.sports("Liga: Equipo A - Equipo B","Fútbol"));assertArrayEquals(new String[]{"Cine: A - B",""},ArchiveText.sports("Cine: A - B","Cine"));}
 @Test public void memoryWindowRetainsSelectedAndPlayerDays(){long now=Instant.parse("2026-10-09T12:00:00Z").toEpochMilli();assertEquals(3,ArchiveWindow.days("2026-10-04",now).size());assertTrue(ArchiveWindow.days("2026-10-04",now).contains("2026-10-08"));assertFalse(ArchiveWindow.retained("2026-09-01T10:00:00Z",now));assertTrue(ArchiveWindow.retained("2026-10-09 10:00:00",now));assertFalse(ArchiveWindow.retained("2026-10-10T10:00:00Z",now));}
}
